CREATE DATABASE IF NOT EXISTS portfolio_db;USE portfolio_db;
CREATE TABLE IF NOT EXISTS contact_messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL,subject VARCHAR(200) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,technologies VARCHAR(255),github_url VARCHAR(255),live_url VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT INTO projects(title,description,technologies) VALUES('Professional Portfolio','Responsive portfolio with contact functionality.','HTML, CSS, JavaScript, Node.js, MySQL'),('Task Management App','Create, update and track tasks using a REST API.','JavaScript, Node.js, Express, MySQL'),('E-Commerce Website','Responsive shopping interface with backend integration.','HTML, CSS, JavaScript, Node.js'),('Fake Profile Detection','Machine-learning project for suspicious profile identification.','Python, Machine Learning, Neural Network');